#!/usr/bin/env node

// 本文件是 gmb-repository.yml 的完整动作入口。
// 所需实现内嵌于本文件，运行时不得导入其它产品或动作脚本。
import { mkdtempSync, realpathSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { spawnSync } from 'node:child_process';

const repositoryRoot = resolve(dirname(fileURLToPath(import.meta.url)), '../../..');
const implementations = Object.freeze({"dependencies":"#!/usr/bin/env node\n\n// 全仓依赖检查只读取受 Git 管理的 manifest、lockfile、工具链和 workflow；\n// 更新必须由人工明确执行并经过产品真实验收，CI/Release 不得自动改写依赖。\nimport { existsSync, readFileSync } from \"node:fs\";\nimport { spawnSync } from \"node:child_process\";\nimport { dirname, resolve } from \"node:path\";\nimport { fileURLToPath } from \"node:url\";\n\nconst repositoryRoot = process.env.GMB_REPOSITORY_ROOT || process.cwd();\nconst contractPath = resolve(repositoryRoot, \".github/dependencies.json\");\nconst contract = JSON.parse(readFileSync(contractPath, \"utf8\"));\nconst [command = \"check\", ...argumentsList] = process.argv.slice(2);\nconst scopeIndex = argumentsList.indexOf(\"--scope\");\nconst scopeName = scopeIndex >= 0 ? argumentsList[scopeIndex + 1] : \"repository\";\nconst shaPattern = /^[0-9a-f]{40}$/;\n\nfunction fail(message) {\n  throw new Error(message);\n}\n\nfunction pathFor(relativePath) {\n  return resolve(repositoryRoot, relativePath);\n}\n\nfunction read(relativePath) {\n  const absolutePath = pathFor(relativePath);\n  if (!existsSync(absolutePath)) {\n    fail(`缺少依赖文件：${relativePath}`);\n  }\n  return readFileSync(absolutePath, \"utf8\");\n}\n\nfunction trackedFiles(patterns) {\n  const result = spawnSync(\"git\", [\"ls-files\", \"--cached\", \"--others\", \"--exclude-standard\", \"--\", ...patterns], {\n    cwd: repositoryRoot,\n    encoding: \"utf8\",\n  });\n  if (result.status !== 0) {\n    fail(`无法读取 Git 文件清单：${result.stderr.trim()}`);\n  }\n  return result.stdout\n    .split(\"\\n\")\n    .filter(Boolean)\n    .filter((relativePath) => existsSync(pathFor(relativePath)));\n}\n\nfunction requireText(relativePath, expected, description) {\n  if (!read(relativePath).includes(expected)) {\n    fail(`${relativePath} 未满足${description}：${expected}`);\n  }\n}\n\n// 中文注释：构建与封装必须按固定顺序出现，避免只命中两个无关字符串却没有形成正式流程。\nfunction requireOrderedText(relativePath, expectedValues, description) {\n  const text = read(relativePath);\n  let offset = -1;\n  for (const expected of expectedValues) {\n    const next = text.indexOf(expected, offset + 1);\n    if (next < 0) fail(`${relativePath} 未满足${description}：${expected}`);\n    offset = next;\n  }\n}\n\nfunction escapeRegex(value) {\n  return value.replace(/[.*+?^${}()|[\\]\\\\]/g, \"\\\\$&\");\n}\n\nfunction exactCargoDependencyVersion(manifest, dependency) {\n  const tableMatch = manifest.match(new RegExp(\n    `^${escapeRegex(dependency)}\\\\s*=\\\\s*\\\\{[^\\\\n}]*\\\\bversion\\\\s*=\\\\s*\"=([^\"]+)\"`,\n    \"m\",\n  ));\n  const scalarMatch = manifest.match(new RegExp(\n    `^${escapeRegex(dependency)}\\\\s*=\\\\s*\"=([^\"]+)\"`,\n    \"m\",\n  ));\n  const match = tableMatch ?? scalarMatch;\n  if (!match) {\n    fail(`citizenchain/node/Cargo.toml 必须准确固定 ${dependency}`);\n  }\n  return match[1];\n}\n\nfunction cargoLockPackageVersion(lock, packageName) {\n  const match = lock.match(new RegExp(\n    `\\\\[\\\\[package\\\\]\\\\]\\\\r?\\\\nname = \"${escapeRegex(packageName)}\"\\\\r?\\\\nversion = \"([^\"]+)\"`,\n  ));\n  if (!match) {\n    fail(`citizenchain/Cargo.lock 缺少 ${packageName}`);\n  }\n  return match[1];\n}\n\nfunction majorMinor(version, dependency) {\n  const match = version.match(/^(0|[1-9][0-9]*)\\.(0|[1-9][0-9]*)\\.(0|[1-9][0-9]*)$/);\n  if (!match) {\n    fail(`${dependency} 不是规范三段版本：${version}`);\n  }\n  return `${match[1]}.${match[2]}`;\n}\n\nfunction checkTauri() {\n  const cargoManifest = read(\"citizenchain/node/Cargo.toml\");\n  const cargoLock = read(\"citizenchain/Cargo.lock\");\n  const npmManifest = JSON.parse(read(\"citizenchain/node/frontend/package.json\"));\n  const npmLock = JSON.parse(read(\"citizenchain/node/frontend/package-lock.json\"));\n  const rootPackage = npmLock.packages?.[\"\"];\n  const rustVersions = {\n    tauri: contract.tauri.core.rust,\n    \"tauri-build\": contract.tauri.build,\n    \"tauri-plugin-dialog\": contract.tauri.plugins.dialog,\n    \"tauri-plugin-process\": contract.tauri.plugins.process,\n    \"tauri-plugin-updater\": contract.tauri.plugins.updater,\n  };\n  const npmVersions = {\n    \"@tauri-apps/api\": contract.tauri.core.api,\n    \"@tauri-apps/cli\": contract.tauri.core.cli,\n    \"@tauri-apps/plugin-dialog\": contract.tauri.plugins.dialog,\n    \"@tauri-apps/plugin-process\": contract.tauri.plugins.process,\n    \"@tauri-apps/plugin-updater\": contract.tauri.plugins.updater,\n  };\n\n  for (const [dependency, expected] of Object.entries(rustVersions)) {\n    if (exactCargoDependencyVersion(cargoManifest, dependency) !== expected) {\n      fail(`citizenchain/node/Cargo.toml 的 ${dependency} 必须准确固定为 ${expected}`);\n    }\n    if (cargoLockPackageVersion(cargoLock, dependency) !== expected) {\n      fail(`citizenchain/Cargo.lock 的 ${dependency} 必须锁定为 ${expected}`);\n    }\n  }\n  for (const [dependency, expected] of Object.entries(npmVersions)) {\n    const manifestVersion = npmManifest.dependencies?.[dependency]\n      ?? npmManifest.devDependencies?.[dependency];\n    const rootVersion = rootPackage?.dependencies?.[dependency]\n      ?? rootPackage?.devDependencies?.[dependency];\n    const lockVersion = npmLock.packages?.[`node_modules/${dependency}`]?.version;\n    if (manifestVersion !== expected || rootVersion !== expected || lockVersion !== expected) {\n      fail(`citizenchain/node/frontend 的 ${dependency} 必须在 manifest 与 lockfile 准确固定为 ${expected}`);\n    }\n  }\n  for (const [packagePath, metadata] of Object.entries(npmLock.packages ?? {})) {\n    if (packagePath.startsWith(\"node_modules/@tauri-apps/cli-\")\n      && metadata.version !== contract.tauri.core.cli) {\n      fail(`${packagePath} 必须与 @tauri-apps/cli 同为 ${contract.tauri.core.cli}`);\n    }\n  }\n\n  const coreMinor = majorMinor(contract.tauri.core.rust, \"tauri\");\n  for (const [dependency, version] of [\n    [\"@tauri-apps/api\", contract.tauri.core.api],\n    [\"@tauri-apps/cli\", contract.tauri.core.cli],\n  ]) {\n    if (majorMinor(version, dependency) !== coreMinor) {\n      fail(`Tauri core 主次版本不一致：tauri=${contract.tauri.core.rust} ${dependency}=${version}`);\n    }\n  }\n\n  const cli = \"node frontend/node_modules/@tauri-apps/cli/tauri.js\";\n  for (const workflow of contract.scopes[\"citizenchain-node\"].workflows) {\n    const text = read(workflow);\n    if (text.includes(\"cargo install tauri-cli\") || /\\bcargo tauri\\b/.test(text)) {\n      fail(`${workflow} 仍依赖浮动或全局 Tauri CLI`);\n    }\n    if (!text.includes(`${cli} build --ci -- --locked`)) {\n      fail(`${workflow} 未使用仓库锁定的 Tauri CLI 构建`);\n    }\n    if (workflow.includes(\"-release-\") && !text.includes(`${cli} signer sign`)) {\n      fail(`${workflow} 未使用仓库锁定的 Tauri CLI 签名 updater`);\n    }\n  }\n  for (const script of [\"citizenchain/scripts/run.sh\", \"citizenchain/scripts/clean-run.sh\"]) {\n    if (/\\bcargo tauri\\b/.test(read(script))) {\n      fail(`${script} 仍依赖本机全局 Tauri CLI`);\n    }\n  }\n  const runScript = \"citizenchain/scripts/run.sh\";\n  requireOrderedText(runScript, [\n    `${cli} build --config \"$tauri_override\"`,\n    `--no-bundle --ci -- --locked`,\n    `${cli} bundle --bundles app --ci`,\n  ], \"仓库 Tauri CLI 正式编译与封装顺序\");\n  if (read(runScript).includes(`${cli} build --bundles app --ci`)) {\n    fail(`${runScript} 禁止恢复编译与封装合并的旧 Tauri 命令`);\n  }\n  requireText(\"citizenchain/scripts/clean-run.sh\", `${cli} dev -- --locked`, \"仓库 Tauri CLI 开发构建\");\n}\n\nfunction checkRequiredFiles(scope) {\n  for (const relativePath of scope.requiredFiles) {\n    read(relativePath);\n  }\n}\n\nfunction checkPackageLocks(projects) {\n  for (const directory of projects) {\n    const manifest = JSON.parse(read(`${directory}/package.json`));\n    const lock = JSON.parse(read(`${directory}/package-lock.json`));\n    const rootPackage = lock.packages?.[\"\"];\n    if (lock.lockfileVersion !== 3) {\n      fail(`${directory}/package-lock.json 必须使用 lockfileVersion 3`);\n    }\n    if (!rootPackage || rootPackage.name !== manifest.name) {\n      fail(`${directory} 的 package.json 与 package-lock.json 包名不一致`);\n    }\n    if (manifest.version && rootPackage.version !== manifest.version) {\n      fail(`${directory} 的 package.json 与 package-lock.json 版本不一致`);\n    }\n  }\n}\n\nfunction dartScalar(relativePath, dependency) {\n  const escaped = dependency.replace(/[.*+?^${}()|[\\]\\\\]/g, \"\\\\$&\");\n  const match = read(relativePath).match(new RegExp(`^  ${escaped}:\\\\s*([^#\\\\n]+?)\\\\s*$`, \"m\"));\n  if (!match) {\n    fail(`${relativePath} 缺少统一 Dart 依赖：${dependency}`);\n  }\n  return match[1].trim();\n}\n\nfunction checkSharedDartDependencies() {\n  for (const dependency of contract.sharedDartDependencies) {\n    const appVersion = dartScalar(\"citizenapp/pubspec.yaml\", dependency);\n    const walletVersion = dartScalar(\"citizenwallet/pubspec.yaml\", dependency);\n    if (appVersion !== walletVersion) {\n      fail(`移动端共享依赖 ${dependency} 版本不一致：CitizenApp=${appVersion} CitizenWallet=${walletVersion}`);\n    }\n  }\n}\n\nfunction checkToolchains(name) {\n  const { node, rust, flutter, java, gradle } = contract.toolchains;\n  const mobileScope = name === \"repository\" || [\"citizenapp\", \"citizenwallet\"].includes(name);\n  const chainScope = name === \"repository\" || [\"citizenchain-node\", \"citizenchain-runtime\"].includes(name);\n  const nodeScope = name === \"repository\" || [\"citizenchain-node\", \"citizenserve\", \"citizenweb\"].includes(name);\n  if (mobileScope) {\n    majorMinor(flutter, \"Flutter\");\n  }\n  const rustFiles = name === \"repository\"\n    ? [\"citizenchain/rust-toolchain.toml\", \"citizenapp/smoldot/ffi/rust-toolchain.toml\"]\n    : name === \"citizenapp\"\n      ? [\"citizenapp/smoldot/ffi/rust-toolchain.toml\"]\n      : chainScope\n        ? [\"citizenchain/rust-toolchain.toml\"]\n        : [];\n  for (const file of rustFiles) {\n    requireText(file, `channel = \"${rust}\"`, \"Rust 版本统一契约\");\n  }\n  const nodeFiles = name === \"repository\"\n    ? [\"citizenchain/node/frontend/.nvmrc\", \"citizenweb/.nvmrc\"]\n    : name === \"citizenchain-node\"\n      ? [\"citizenchain/node/frontend/.nvmrc\"]\n      : name === \"citizenweb\"\n        ? [\"citizenweb/.nvmrc\"]\n        : [];\n  for (const file of nodeFiles) {\n    if (read(file).trim() !== node) {\n      fail(`${file} 必须精确固定 Node.js ${node}`);\n    }\n  }\n  const gradleFiles = name === \"repository\"\n    ? [\n        \"citizenapp/android/gradle/wrapper/gradle-wrapper.properties\",\n        \"citizenwallet/android/gradle/wrapper/gradle-wrapper.properties\",\n      ]\n    : name === \"citizenapp\"\n      ? [\"citizenapp/android/gradle/wrapper/gradle-wrapper.properties\"]\n      : name === \"citizenwallet\"\n        ? [\"citizenwallet/android/gradle/wrapper/gradle-wrapper.properties\"]\n        : [];\n  for (const file of gradleFiles) {\n    requireText(file, `gradle-${gradle}-all.zip`, \"Gradle 版本统一契约\");\n  }\n  const workflows = name === \"repository\"\n    ? trackedFiles([\n      \".github/workflows/*.yml\",\n      \".github/workflows/*.yaml\",\n      \".github/workflows/*/*.yml\",\n      \".github/workflows/*/*.yaml\",\n    ])\n    : contract.scopes[name].workflows;\n  for (const workflow of workflows) {\n    const text = read(workflow);\n    if (/node-version:\\s*(?:['\"])?25(?:['\"])?\\s*$/m.test(text)) {\n      fail(`${workflow} 仍使用浮动 Node.js 25，必须精确固定 ${node}`);\n    }\n    if (nodeScope && text.includes(\"node-version:\") && !text.includes(`node-version: ${node}`)) {\n      fail(`${workflow} 的 Node.js 版本未统一为 ${node}`);\n    }\n    if (text.includes(\"java-version:\") && !text.includes(`java-version: ${java}`)) {\n      fail(`${workflow} 的 Java 版本未统一为 ${java}`);\n    }\n  }\n}\n\nfunction checkActions(workflows) {\n  for (const [action, sha] of Object.entries(contract.actions)) {\n    if (!shaPattern.test(sha)) {\n      fail(`${action} 未配置完整 commit SHA`);\n    }\n  }\n  for (const workflow of workflows) {\n    const text = read(workflow);\n    for (const match of text.matchAll(/^\\s*uses:\\s*([^\\s#]+)(?:\\s+#.*)?$/gm)) {\n      const reference = match[1];\n      if (reference.startsWith(\"./\") || reference.startsWith(\"docker://\")) {\n        continue;\n      }\n      const separator = reference.lastIndexOf(\"@\");\n      const action = reference.slice(0, separator);\n      const revision = reference.slice(separator + 1);\n      if (!contract.actions[action]) {\n        fail(`${workflow} 使用了未登记 Action：${action}`);\n      }\n      if (revision !== contract.actions[action]) {\n        fail(`${workflow} 的 ${action} 未固定到统一 SHA ${contract.actions[action]}`);\n      }\n    }\n  }\n}\n\nfunction checkOfficialRunners(workflows) {\n  const allowed = new Set(contract.officialRunners);\n  for (const workflow of workflows) {\n    const text = read(workflow);\n    if (/runs-on:\\s*(?:\\[[^\\]]*\\bself-hosted\\b|\\bself-hosted\\b)/m.test(text)) {\n      fail(`${workflow} 使用了 self-hosted runner，必须使用统一官方镜像`);\n    }\n    const runnerLabels = [\n      ...text.matchAll(/^\\s*runs-on:\\s*((?:ubuntu|macos|windows)-[a-zA-Z0-9.-]+)\\s*$/gm),\n      ...text.matchAll(/[\"']os[\"']\\s*:\\s*[\"']((?:ubuntu|macos|windows)-[a-zA-Z0-9.-]+)[\"']/g),\n    ];\n    for (const match of runnerLabels) {\n      if (!allowed.has(match[1])) {\n        fail(`${workflow} 使用了未登记的 runner 镜像：${match[1]}`);\n      }\n    }\n  }\n}\n\nfunction checkGitDependencies(manifests) {\n  for (const manifest of manifests) {\n    const text = read(manifest);\n    if (/git\\s*=\\s*\"[^\"]+\"[^\\n}]*\\b(branch|tag)\\s*=/m.test(text)) {\n      fail(`${manifest} 存在可漂移的 Git branch/tag 依赖，必须使用 rev`);\n    }\n    for (const match of text.matchAll(/git\\s*=\\s*\"[^\"]+\"[^\\n}]*\\brev\\s*=\\s*\"([^\"]+)\"/g)) {\n      if (!shaPattern.test(match[1])) {\n        fail(`${manifest} 的 Git rev 不是完整 commit SHA：${match[1]}`);\n      }\n    }\n  }\n}\n\n// 中文注释：本地路径依赖必须从声明它的 manifest 目录解析；仅检查文件存在会漏掉\n// Cargo workspace 解析错误，因此全仓还会逐个执行 cargo metadata。\nfunction checkLocalDependencyPaths() {\n  const cargoManifests = trackedFiles([\"**/Cargo.toml\", \"Cargo.toml\"]);\n  for (const manifest of cargoManifests) {\n    const manifestDirectory = dirname(pathFor(manifest));\n    for (const match of read(manifest).matchAll(/\\bpath\\s*=\\s*\"([^\"]+)\"/g)) {\n      if (!existsSync(resolve(manifestDirectory, match[1]))) {\n        fail(`${manifest} 的 Cargo 本地依赖不存在：${match[1]}`);\n      }\n    }\n  }\n\n  const dartManifests = trackedFiles([\"**/pubspec.yaml\", \"pubspec.yaml\"]);\n  for (const manifest of dartManifests) {\n    const manifestDirectory = dirname(pathFor(manifest));\n    for (const match of read(manifest).matchAll(/^ {4}path:\\s*([^#\\n]+?)\\s*$/gm)) {\n      const dependencyPath = match[1].trim().replace(/^['\"]|['\"]$/g, \"\");\n      if (!existsSync(resolve(manifestDirectory, dependencyPath))) {\n        fail(`${manifest} 的 Dart 本地依赖不存在：${dependencyPath}`);\n      }\n    }\n  }\n\n  const npmManifests = trackedFiles([\"**/package.json\", \"package.json\"])\n    .filter((manifest) => !manifest.includes(\"/dist/\"));\n  for (const manifest of npmManifests) {\n    const manifestDirectory = dirname(pathFor(manifest));\n    const packageManifest = JSON.parse(read(manifest));\n    for (const dependencies of [\n      packageManifest.dependencies,\n      packageManifest.devDependencies,\n      packageManifest.optionalDependencies,\n    ]) {\n      for (const [dependency, version] of Object.entries(dependencies ?? {})) {\n        if (typeof version !== \"string\" || !version.startsWith(\"file:\")) continue;\n        const dependencyPath = version.slice(\"file:\".length);\n        if (!existsSync(resolve(manifestDirectory, dependencyPath))) {\n          fail(`${manifest} 的 npm 本地依赖 ${dependency} 不存在：${dependencyPath}`);\n        }\n      }\n    }\n  }\n}\n\nfunction checkCargoMetadata() {\n  for (const directory of contract.cargoProjects) {\n    console.log(`\\n[${directory}] cargo metadata --format-version 1 --locked --no-deps`);\n    const result = spawnSync(\n      \"cargo\",\n      [\"metadata\", \"--format-version\", \"1\", \"--locked\", \"--no-deps\"],\n      { cwd: pathFor(directory), encoding: \"utf8\" },\n    );\n    if (result.error) fail(`无法执行 cargo metadata：${result.error.message}`);\n    if (result.status !== 0) {\n      const detail = (result.stderr || result.stdout || \"\").trim();\n      fail(`${directory} 的 Cargo workspace 无法解析：${detail}`);\n    }\n  }\n}\n\nfunction workflowActionScript(workflow) {\n  if (workflow === '.github/workflows/gmb-repository.yml') {\n    return '.github/scripts/gmb-repository/ci-repository.mjs';\n  }\n  return workflow.replace(/^\\.github\\/workflows\\//, '.github/scripts/').replace(/\\.ya?ml$/, '.mjs');\n}\n\nfunction checkWorkflowScopes() {\n  const productWorkflows = [];\n  const expectedWorkflows = [];\n  const legacyName = `${\"gmb-ci\"}-repository.yml`;\n  for (const [name, scope] of Object.entries(contract.scopes)) {\n    for (const workflow of scope.workflows) {\n      expectedWorkflows.push(workflow);\n      const text = read(workflow);\n      const invocation = `node ${workflowActionScript(workflow)} dependencies check --scope ${name}`;\n      if (!text.includes(invocation)) {\n        fail(`${workflow} 未调用依赖作用域：${name}`);\n      }\n      if (name !== \"repository\") {\n        productWorkflows.push(workflow);\n        if (text.includes(\"gmb-repository.yml\") || text.includes(legacyName)) {\n          fail(`${workflow} 不得调用或依赖仓库门禁`);\n        }\n      }\n    }\n  }\n  if (productWorkflows.length !== 22) {\n    fail(`产品 CI/Release workflow 必须精确为 22 条，当前契约登记 ${productWorkflows.length} 条`);\n  }\n  const actualWorkflows = trackedFiles([\n    \".github/workflows/*.yml\",\n    \".github/workflows/*.yaml\",\n    \".github/workflows/*/*.yml\",\n    \".github/workflows/*/*.yaml\",\n  ]);\n  const expected = [...expectedWorkflows].sort();\n  const actual = [...actualWorkflows].sort();\n  if (JSON.stringify(actual) !== JSON.stringify(expected)) {\n    fail(`workflow 清单与依赖契约不一致：期望 ${expected.length} 条，实际 ${actual.length} 条`);\n  }\n  const legacyWorkflow = `.github/workflows/${\"gmb-ci\"}-repository.yml`;\n  if (existsSync(pathFor(legacyWorkflow))) {\n    fail(`旧仓库门禁 ${legacyWorkflow} 仍存在`);\n  }\n}\n\nfunction checkFrozenCommands(scopeNames) {\n  for (const name of scopeNames) {\n    const scope = contract.scopes[name];\n    for (const workflow of scope.workflows) {\n      const text = read(workflow);\n      if ([\"citizenapp\", \"citizenwallet\"].includes(name) && !text.includes(\"flutter pub get --enforce-lockfile\")) {\n        fail(`${workflow} 未冻结 Flutter/Dart 应用依赖`);\n      }\n      if ([\"citizenserve\", \"citizenweb\"].includes(name) && !text.includes(\"npm ci\")) {\n        fail(`${workflow} 未使用 npm ci`);\n      }\n      if ([\"citizenchain-node\", \"citizenchain-runtime\"].includes(name) && !text.includes(\"--locked\")) {\n        fail(`${workflow} 未冻结 Cargo 依赖`);\n      }\n    }\n  }\n}\n\nfunction checkAuditGates(scopeNames) {\n  for (const name of scopeNames) {\n    const scope = contract.scopes[name];\n    const audited = contract.auditedScopes.includes(name);\n    const hasCargo = contract.cargoProjects.some((directory) =>\n      scope.requiredFiles.includes(projectFile(directory, \"Cargo.toml\")));\n    for (const workflow of scope.workflows) {\n      const invocation = `node ${workflowActionScript(workflow)} dependencies audit --scope ${name}`;\n      const text = read(workflow);\n      if (audited && !text.includes(invocation)) {\n        fail(`${workflow} 未接入已清零产品的阻断安全审计：${name}`);\n      }\n      if (!audited && text.includes(invocation)) {\n        fail(`${workflow} 接入了尚未登记零漏洞基线的安全审计：${name}`);\n      }\n      if (audited && hasCargo && !text.includes(\n        `cargo install cargo-audit --version ${contract.toolchains.cargoAudit} --locked`,\n      )) {\n        fail(`${workflow} 未安装固定版本 cargo-audit ${contract.toolchains.cargoAudit}`);\n      }\n    }\n  }\n}\n\nfunction checkScope(name) {\n  const scope = contract.scopes[name];\n  if (!scope) {\n    fail(`未知依赖作用域：${name}`);\n  }\n  checkRequiredFiles(scope);\n  if (name === \"repository\" || name === \"citizenchain-node\") {\n    checkTauri();\n  }\n  if (name === \"repository\") {\n    for (const candidate of Object.values(contract.scopes)) {\n      checkRequiredFiles(candidate);\n    }\n    checkPackageLocks(contract.npmProjects);\n    for (const directory of contract.dartApplications) {\n      read(`${directory}/pubspec.yaml`);\n      read(`${directory}/pubspec.lock`);\n    }\n    for (const directory of contract.cargoProjects) {\n      read(`${directory}/Cargo.toml`);\n      read(`${directory}/Cargo.lock`);\n    }\n    checkSharedDartDependencies();\n    checkToolchains(name);\n    const workflows = trackedFiles([\n      \".github/workflows/*.yml\",\n      \".github/workflows/*.yaml\",\n      \".github/workflows/*/*.yml\",\n      \".github/workflows/*/*.yaml\",\n    ]);\n    checkActions(workflows);\n    checkOfficialRunners(workflows);\n    checkGitDependencies(trackedFiles([\"**/Cargo.toml\", \"Cargo.toml\"]));\n    checkLocalDependencyPaths();\n    checkCargoMetadata();\n    checkWorkflowScopes();\n    checkFrozenCommands(Object.keys(contract.scopes));\n    checkAuditGates(Object.keys(contract.scopes));\n  } else {\n    checkPackageLocks(contract.npmProjects.filter((directory) =>\n      scope.requiredFiles.includes(`${directory}/package.json`)));\n    checkToolchains(name);\n    checkActions(scope.workflows);\n    checkOfficialRunners(scope.workflows);\n    checkGitDependencies(scope.requiredFiles.filter((file) => file.endsWith(\"Cargo.toml\")));\n    checkFrozenCommands([name]);\n    checkAuditGates([name]);\n    for (const workflow of scope.workflows) {\n      const invocation = `node ${workflowActionScript(workflow)} dependencies check --scope ${name}`;\n      requireText(workflow, invocation, \"产品依赖作用域检查\");\n    }\n  }\n  console.log(`依赖检查通过：${name}`);\n}\n\nfunction projectFile(directory, fileName) {\n  return directory === \".\" ? fileName : `${directory}/${fileName}`;\n}\n\nfunction scopedProjects(projects, fileName) {\n  if (scopeName === \"repository\") {\n    return projects;\n  }\n  const requiredFiles = contract.scopes[scopeName]?.requiredFiles;\n  if (!requiredFiles) {\n    fail(`未知依赖作用域：${scopeName}`);\n  }\n  return projects.filter((directory) => requiredFiles.includes(projectFile(directory, fileName)));\n}\n\nfunction runNative(executable, argumentsValue, cwd, allowFailure = false) {\n  console.log(`\\n[${cwd}] ${executable} ${argumentsValue.join(\" \")}`);\n  const result = spawnSync(executable, argumentsValue, {\n    cwd: pathFor(cwd),\n    encoding: \"utf8\",\n    stdio: \"inherit\",\n  });\n  if (result.error) {\n    fail(`无法执行 ${executable}：${result.error.message}`);\n  }\n  if (result.status !== 0 && !allowFailure) {\n    fail(`${executable} 检查失败，退出码 ${result.status}`);\n  }\n}\n\nfunction audit() {\n  checkScope(scopeName);\n  const npmProjects = scopedProjects(contract.npmProjects, \"package.json\");\n  const cargoProjects = scopedProjects(contract.cargoProjects, \"Cargo.toml\");\n  for (const directory of npmProjects) {\n    runNative(\"npm\", [\"audit\", \"--audit-level=low\"], directory);\n  }\n  if (cargoProjects.length > 0) {\n    const auditVersion = spawnSync(\"cargo\", [\"audit\", \"--version\"], { encoding: \"utf8\" });\n    if (auditVersion.status !== 0 || !auditVersion.stdout.includes(contract.toolchains.cargoAudit)) {\n      fail(`cargo-audit 必须安装并固定为 ${contract.toolchains.cargoAudit}`);\n    }\n    for (const [index, directory] of cargoProjects.entries()) {\n      const argumentsValue = [\"audit\"];\n      if (index > 0) {\n        argumentsValue.push(\"--no-fetch\");\n      }\n      argumentsValue.push(\"--file\", projectFile(directory, \"Cargo.lock\"));\n      runNative(\"cargo\", argumentsValue, \".\");\n    }\n  }\n}\n\nfunction outdated() {\n  checkScope(scopeName);\n  for (const directory of scopedProjects(contract.npmProjects, \"package.json\")) {\n    runNative(\"npm\", [\"outdated\"], directory, true);\n  }\n  for (const directory of scopedProjects(contract.dartApplications, \"pubspec.yaml\")) {\n    runNative(\"dart\", [\"pub\", \"outdated\"], directory, true);\n  }\n  for (const directory of scopedProjects(contract.cargoProjects, \"Cargo.toml\")) {\n    runNative(\"cargo\", [\"update\", \"--dry-run\", \"--manifest-path\", projectFile(directory, \"Cargo.toml\")], \".\", true);\n  }\n  console.log(\"\\n过期版本仅报告；更新 manifest/lockfile 后必须重新执行产品真实验收。\");\n}\n\ntry {\n  if (contract.schema !== 1) {\n    fail(`不支持依赖契约 schema：${contract.schema}`);\n  }\n  if (command === \"check\") {\n    checkScope(scopeName);\n  } else if (command === \"audit\") {\n    audit();\n  } else if (command === \"outdated\") {\n    outdated();\n  } else {\n    fail(`未知命令：${command}`);\n  }\n} catch (error) {\n  console.error(`依赖检查失败：${error.message}`);\n  process.exitCode = 1;\n}\n","data-dictionary":"#!/usr/bin/env node\n\nimport { execFileSync } from 'node:child_process';\nimport { existsSync, readFileSync } from 'node:fs';\nimport { dirname, extname, join, resolve } from 'node:path';\nimport { fileURLToPath, pathToFileURL } from 'node:url';\n\nconst scriptPath = fileURLToPath(import.meta.url);\nconst repositoryRoot = process.env.GMB_REPOSITORY_ROOT || process.cwd();\n// 中文注释：统一数据字典属于 GMB 公开跨产品契约，公开门禁不得反向依赖私人 AI 规则。\nconst dictionaryPath = join(repositoryRoot, 'shared/data-dictionary.json');\nconst sourceExtensions = /\\.(?:dart|js|jsx|json|kts?|md|mjs|proto|py|rs|sh|sql|swift|toml|tsx?|ya?ml)$/;\nconst authorities = new Set(['gmb', 'polkadot_sdk']);\nconst dataTypes = new Set(['array', 'boolean', 'enum', 'hash', 'hex_32', 'integer', 'string']);\nconst valueTypes = new Set(['boolean', 'integer', 'string']);\n\nfunction fail(message) {\n  throw new Error(message);\n}\n\nexport function toCamelCase(fieldName) {\n  return fieldName.replace(/_([a-z0-9])/g, (_, value) => value.toUpperCase());\n}\n\nexport function toSnakeCase(fieldName) {\n  return fieldName.replace(/([a-z0-9])([A-Z])/g, '$1_$2').toLowerCase();\n}\n\nfunction escapeRegex(value) {\n  return value.replace(/[.*+?^${}()|[\\]\\\\]/g, '\\\\$&');\n}\n\nexport function globToRegex(glob) {\n  let pattern = '';\n  for (let index = 0; index < glob.length; index += 1) {\n    const char = glob[index];\n    if (char !== '*') {\n      pattern += escapeRegex(char);\n      continue;\n    }\n    if (glob[index + 1] === '*') {\n      index += 1;\n      if (glob[index + 1] === '/') {\n        index += 1;\n        pattern += '(?:.*/)?';\n      } else {\n        pattern += '.*';\n      }\n    } else {\n      pattern += '[^/]*';\n    }\n  }\n  return new RegExp(`^${pattern}$`);\n}\n\nfunction matchesAny(path, globs) {\n  return globs.some((glob) => globToRegex(glob).test(path));\n}\n\nfunction sortedUnique(values, label, selector = (value) => value) {\n  if (!Array.isArray(values)) fail(`${label} 必须是数组`);\n  const keys = values.map(selector);\n  if (keys.some((value) => typeof value !== 'string' || value.length === 0)) {\n    fail(`${label} 存在空值或非字符串标识`);\n  }\n  if (new Set(keys).size !== keys.length) fail(`${label} 存在重复项`);\n  const sorted = [...keys].sort();\n  if (JSON.stringify(sorted) !== JSON.stringify(keys)) fail(`${label} 必须按字典序排列`);\n}\n\nfunction exactKeys(value, expected, label) {\n  if (!value || typeof value !== 'object' || Array.isArray(value)) fail(`${label} 必须是对象`);\n  const actual = Object.keys(value).sort();\n  const sortedExpected = [...expected].sort();\n  if (JSON.stringify(actual) !== JSON.stringify(sortedExpected)) {\n    fail(`${label} 属性无效：只允许 ${expected.join(', ')}`);\n  }\n}\n\nfunction nonEmptyText(value, label) {\n  if (typeof value !== 'string' || value.trim() !== value || value.length === 0) {\n    fail(`${label} 必须是无首尾空白的非空字符串`);\n  }\n}\n\nfunction validateClosedValue(value, valueType, label) {\n  if (typeof value !== valueType) fail(`${label}.value 必须是 ${valueType}`);\n  if (valueType !== 'string') return;\n  nonEmptyText(value, `${label}.value`);\n  if (value.length > 80) fail(`${label}.value 过长，不属于精简闭集值`);\n  if (/^https?:\\/\\//i.test(value)\n      || /^0x[0-9a-f]{64}$/i.test(value)\n      || /^[0-9a-f]{8}-[0-9a-f-]{27,}$/i.test(value)\n      || /^\\d{4}-\\d{2}-\\d{2}(?:T|$)/.test(value)) {\n    fail(`${label}.value 疑似动态 URL、哈希、ID 或时间，不得进入闭集值`);\n  }\n}\n\nfunction validateConcept(concept, label) {\n  const expected = ['concept_id', 'field_name', 'field_name_zh', 'authority', 'data_type', 'forbidden_names'];\n  if ('value_set_id' in concept) expected.push('value_set_id');\n  if ('paths' in concept) expected.push('paths');\n  if ('legacy_reads' in concept) expected.push('legacy_reads');\n  exactKeys(concept, expected, label);\n  if (!/^[a-z][a-z0-9]*(?:_[a-z0-9]+)*$/.test(concept.concept_id)) {\n    fail(`${label}.concept_id 必须使用 snake_case`);\n  }\n  if (!/^[a-z][a-z0-9]*(?:_[a-z0-9]+)*$/.test(concept.field_name)) {\n    fail(`${label}.field_name 必须使用 snake_case`);\n  }\n  nonEmptyText(concept.field_name_zh, `${label}.field_name_zh`);\n  if (!authorities.has(concept.authority)) fail(`${label}.authority 无效`);\n  if (!dataTypes.has(concept.data_type)) fail(`${label}.data_type 无效`);\n  if (concept.data_type === 'enum' && !concept.value_set_id) fail(`${label} 枚举字段缺少 value_set_id`);\n  if (concept.data_type !== 'enum' && concept.value_set_id) fail(`${label} 非枚举字段不得引用 value_set_id`);\n  sortedUnique(concept.forbidden_names, `${label}.forbidden_names`);\n  const canonicalNames = new Set([concept.field_name, toCamelCase(concept.field_name)]);\n  for (const forbiddenName of concept.forbidden_names) {\n    if (!/^[A-Za-z][A-Za-z0-9_]*$/.test(forbiddenName)) fail(`${label} 废弃字段名无效：${forbiddenName}`);\n    if (canonicalNames.has(forbiddenName)) fail(`${label} 把规范字段形式误登记为废弃名：${forbiddenName}`);\n  }\n  if (concept.paths) sortedUnique(concept.paths, `${label}.paths`);\n  if (concept.legacy_reads) {\n    sortedUnique(\n      concept.legacy_reads,\n      `${label}.legacy_reads`,\n      (entry) => `${entry?.field_name ?? ''}:${entry?.path ?? ''}`,\n    );\n    for (const [index, entry] of concept.legacy_reads.entries()) {\n      const entryLabel = `${label}.legacy_reads[${index}]`;\n      exactKeys(entry, ['field_name', 'path'], entryLabel);\n      if (!concept.forbidden_names.includes(entry.field_name)) {\n        fail(`${entryLabel}.field_name 必须同时登记为废弃字段名`);\n      }\n      nonEmptyText(entry.path, `${entryLabel}.path`);\n      if (entry.path.includes('*') || !sourceExtensions.test(entry.path)) {\n        fail(`${entryLabel}.path 必须是精确源码文件路径`);\n      }\n      if (concept.paths && !matchesAny(entry.path, concept.paths)) {\n        fail(`${entryLabel}.path 不在字段受控路径内`);\n      }\n    }\n  }\n}\n\nfunction validateValueSet(valueSet, label) {\n  exactKeys(valueSet, ['value_set_id', 'value_set_zh', 'authority', 'value_type', 'forbidden_values', 'values'], label);\n  if (!/^[a-z][a-z0-9]*(?:_[a-z0-9]+)*$/.test(valueSet.value_set_id)) {\n    fail(`${label}.value_set_id 必须使用 snake_case`);\n  }\n  nonEmptyText(valueSet.value_set_zh, `${label}.value_set_zh`);\n  if (!authorities.has(valueSet.authority)) fail(`${label}.authority 无效`);\n  if (!valueTypes.has(valueSet.value_type)) fail(`${label}.value_type 无效`);\n  sortedUnique(valueSet.forbidden_values, `${label}.forbidden_values`);\n  if (!Array.isArray(valueSet.values) || valueSet.values.length === 0) fail(`${label}.values 必须是非空数组`);\n  const values = [];\n  for (let index = 0; index < valueSet.values.length; index += 1) {\n    const entry = valueSet.values[index];\n    const entryLabel = `${label}.values[${index}]`;\n    exactKeys(entry, ['value', 'full_name_en', 'short_name_en', 'full_name_zh', 'short_name_zh'], entryLabel);\n    validateClosedValue(entry.value, valueSet.value_type, entryLabel);\n    for (const key of ['full_name_en', 'full_name_zh']) nonEmptyText(entry[key], `${entryLabel}.${key}`);\n    for (const [shortKey, fullKey] of [['short_name_en', 'full_name_en'], ['short_name_zh', 'full_name_zh']]) {\n      if (entry[shortKey] === null) continue;\n      nonEmptyText(entry[shortKey], `${entryLabel}.${shortKey}`);\n      if (entry[shortKey] === entry[fullKey]) fail(`${entryLabel}.${shortKey} 与全称重复，应改为 null`);\n    }\n    values.push(String(entry.value));\n  }\n  sortedUnique(values, `${label}.values.value`);\n  const allowed = new Set(values);\n  for (const forbidden of valueSet.forbidden_values) {\n    if (allowed.has(String(forbidden))) fail(`${label} 把规范值误登记为废弃值：${forbidden}`);\n  }\n}\n\nfunction validateContract(contract, label) {\n  exactKeys(contract, ['contract_id', 'contract_name_zh', 'authority', 'paths', 'fields', 'value_sets'], label);\n  if (!/^[a-z][a-z0-9]*(?:_[a-z0-9]+)*$/.test(contract.contract_id)) fail(`${label}.contract_id 必须使用 snake_case`);\n  nonEmptyText(contract.contract_name_zh, `${label}.contract_name_zh`);\n  if (!authorities.has(contract.authority)) fail(`${label}.authority 无效`);\n  sortedUnique(contract.paths, `${label}.paths`);\n  sortedUnique(contract.fields, `${label}.fields`);\n  sortedUnique(contract.value_sets, `${label}.value_sets`);\n  if (contract.paths.length === 0 || contract.fields.length === 0) fail(`${label} 必须声明路径和字段`);\n}\n\nexport function validateDictionary(index, shards, jsonFiles = []) {\n  exactKeys(index, ['domains', 'ignored_paths'], 'index.json');\n  sortedUnique(index.domains, 'index.json.domains', (domain) => domain?.domain_id);\n  sortedUnique(index.ignored_paths, 'index.json.ignored_paths');\n  const indexedFiles = new Set(['index.json']);\n  for (const domain of index.domains) {\n    exactKeys(domain, ['domain_id', 'file'], `index.json.domains.${domain.domain_id ?? '未知'}`);\n    if (!/^[a-z][a-z0-9]*$/.test(domain.domain_id)) fail(`领域标识无效：${domain.domain_id}`);\n    if (domain.file !== `${domain.domain_id}.json`) fail(`${domain.domain_id} 的文件必须是 ${domain.domain_id}.json`);\n    indexedFiles.add(domain.file);\n  }\n  if (jsonFiles.length > 0) {\n    sortedUnique(jsonFiles, '数据字典 JSON 文件');\n    const expected = [...indexedFiles].sort();\n    if (JSON.stringify(jsonFiles) !== JSON.stringify(expected)) fail('数据字典存在未索引或缺失的 JSON 分片');\n  }\n  if (shards.length !== index.domains.length) fail('数据字典分片数量与索引不一致');\n\n  const concepts = new Map();\n  const fieldNames = new Map();\n  const valueSets = new Map();\n  const contracts = new Map();\n  for (let shardIndex = 0; shardIndex < shards.length; shardIndex += 1) {\n    const shard = shards[shardIndex];\n    const domain = index.domains[shardIndex];\n    exactKeys(shard, ['domain_id', 'concepts', 'value_sets', 'contracts'], domain.file);\n    if (shard.domain_id !== domain.domain_id) fail(`${domain.file} 的 domain_id 不一致`);\n    sortedUnique(shard.concepts, `${domain.file}.concepts`, (entry) => entry?.concept_id);\n    sortedUnique(shard.value_sets, `${domain.file}.value_sets`, (entry) => entry?.value_set_id);\n    sortedUnique(shard.contracts, `${domain.file}.contracts`, (entry) => entry?.contract_id);\n    shard.concepts.forEach((concept, index) => {\n      validateConcept(concept, `${domain.file}.concepts[${index}]`);\n      if (concepts.has(concept.concept_id)) fail(`concept_id 跨分片重复：${concept.concept_id}`);\n      if (fieldNames.has(concept.field_name)) fail(`field_name 跨分片重复：${concept.field_name}`);\n      concepts.set(concept.concept_id, concept);\n      fieldNames.set(concept.field_name, concept.concept_id);\n    });\n    shard.value_sets.forEach((valueSet, index) => {\n      validateValueSet(valueSet, `${domain.file}.value_sets[${index}]`);\n      if (valueSets.has(valueSet.value_set_id)) fail(`value_set_id 跨分片重复：${valueSet.value_set_id}`);\n      valueSets.set(valueSet.value_set_id, valueSet);\n    });\n    shard.contracts.forEach((contract, index) => {\n      validateContract(contract, `${domain.file}.contracts[${index}]`);\n      if (contracts.has(contract.contract_id)) fail(`contract_id 跨分片重复：${contract.contract_id}`);\n      contracts.set(contract.contract_id, contract);\n    });\n  }\n\n  const referencedFields = new Set();\n  const referencedValueSets = new Set();\n  for (const concept of concepts.values()) {\n    if (concept.value_set_id && !valueSets.has(concept.value_set_id)) {\n      fail(`${concept.concept_id} 引用了不存在的 value_set_id：${concept.value_set_id}`);\n    }\n  }\n  for (const contract of contracts.values()) {\n    const expectedValueSets = new Set();\n    for (const conceptId of contract.fields) {\n      if (!concepts.has(conceptId)) fail(`${contract.contract_id} 引用了不存在的字段：${conceptId}`);\n      referencedFields.add(conceptId);\n      const valueSetId = concepts.get(conceptId).value_set_id;\n      if (valueSetId) expectedValueSets.add(valueSetId);\n    }\n    for (const valueSetId of contract.value_sets) {\n      if (!valueSets.has(valueSetId)) fail(`${contract.contract_id} 引用了不存在的值集：${valueSetId}`);\n      referencedValueSets.add(valueSetId);\n    }\n    if (JSON.stringify([...expectedValueSets].sort()) !== JSON.stringify(contract.value_sets)) {\n      fail(`${contract.contract_id} 的 value_sets 必须与枚举字段引用完全一致`);\n    }\n  }\n  for (const conceptId of concepts.keys()) {\n    if (!referencedFields.has(conceptId)) fail(`字段未进入任何契约：${conceptId}`);\n  }\n  for (const valueSetId of valueSets.keys()) {\n    if (!referencedValueSets.has(valueSetId)) fail(`值集未进入任何契约：${valueSetId}`);\n  }\n  return { concepts, valueSets, contracts, ignoredPaths: index.ignored_paths };\n}\n\nexport function loadDictionary() {\n  const dictionary = JSON.parse(readFileSync(dictionaryPath, 'utf8'));\n  exactKeys(dictionary, ['fields', 'value_sets', 'contracts', 'ignored_paths'], 'data-dictionary.json');\n  sortedUnique(dictionary.fields, 'data-dictionary.json.fields', (entry) => entry?.concept_id);\n  sortedUnique(dictionary.value_sets, 'data-dictionary.json.value_sets', (entry) => entry?.value_set_id);\n  sortedUnique(dictionary.contracts, 'data-dictionary.json.contracts', (entry) => entry?.contract_id);\n  sortedUnique(dictionary.ignored_paths, 'data-dictionary.json.ignored_paths');\n\n  const entries = [...dictionary.fields, ...dictionary.value_sets, ...dictionary.contracts];\n  const domains = [...new Set(entries.map((entry) => entry?.domain))].sort();\n  if (domains.some((domain) => typeof domain !== 'string' || !/^[a-z][a-z0-9]*$/.test(domain))) {\n    fail('data-dictionary.json 存在无效领域标识');\n  }\n  const withoutDomain = (entry) => {\n    const { domain: _domain, ...value } = entry;\n    return value;\n  };\n  const index = {\n    domains: domains.map((domainId) => ({ domain_id: domainId, file: `${domainId}.json` })),\n    ignored_paths: dictionary.ignored_paths,\n  };\n  const shards = domains.map((domainId) => ({\n    domain_id: domainId,\n    concepts: dictionary.fields.filter((entry) => entry.domain === domainId).map(withoutDomain),\n    value_sets: dictionary.value_sets.filter((entry) => entry.domain === domainId).map(withoutDomain),\n    contracts: dictionary.contracts.filter((entry) => entry.domain === domainId).map(withoutDomain),\n  }));\n  return validateDictionary(index, shards);\n}\n\n// 中文注释：只把声明、对象键、序列化键和数据库列视为字段，避免把函数名中的同词根误判为契约字段。\nfunction fieldPatterns(fieldName) {\n  const escaped = escapeRegex(fieldName);\n  return [\n    new RegExp(`['\\\"]${escaped}['\\\"]\\\\s*:`),\n    new RegExp(`\\\\[['\\\"]${escaped}['\\\"]\\\\]`),\n    new RegExp(`\\\\b(?:this\\\\.)?${escaped}\\\\b\\\\s*[?!]?\\\\s*:`),\n    new RegExp(`\\\\bthis\\\\.${escaped}\\\\b`),\n    new RegExp(`\\\\b${escaped}\\\\b\\\\s*[;=]`),\n    new RegExp(`^\\\\s*${escaped}\\\\s+(?:BIGINT|BLOB|BOOLEAN|INTEGER|REAL|TEXT)\\\\b`, 'i'),\n    new RegExp(`rename(?:_all)?\\\\s*=\\\\s*['\\\"]${escaped}['\\\"]`),\n  ];\n}\n\n// 中文注释：旧字段只允许作为数据字典明确登记的单向读取键；Rust/TS/Dart 标识符仍必须使用规范名。\nexport function isDeclaredLegacyRead(line, path, fieldName, legacyReads = []) {\n  if (!legacyReads.some((entry) => entry.field_name === fieldName && entry.path === path)) return false;\n  const escaped = escapeRegex(fieldName);\n  return new RegExp(`(?:rename\\\\s*=\\\\s*['\\\"]${escaped}['\\\"]|['\\\"]${escaped}['\\\"]\\\\s*:)`).test(line);\n}\n\nexport function lineUsesFieldName(line, fieldName) {\n  return fieldPatterns(fieldName).some((pattern) => pattern.test(line));\n}\n\nexport function markdownUsesFieldName(line, fieldName) {\n  if (!/(字段|参数|载荷|协议|API|DTO|JSON|SQL|storage|Storage)/i.test(line)) return false;\n  if (/(禁止|不得|废弃|旧名|历史|拒绝|不再|零命中)/.test(line)) return false;\n  return new RegExp(`\\`${escapeRegex(fieldName)}\\``).test(line);\n}\n\n// 中文注释：增量门禁只提取能形成跨文件或强序列化契约的字段；普通局部变量不会仅因赋值进入字典。\nexport function addedFieldNames(line, extension = '') {\n  const fields = new Map();\n  const add = (fieldName, strong = false) => {\n    if (!/^[a-z][A-Za-z0-9_]{2,}$/.test(fieldName)) return;\n    const normalized = toSnakeCase(fieldName);\n    const previous = fields.get(normalized);\n    fields.set(normalized, { fieldName: normalized, strong: strong || previous?.strong || false });\n  };\n  for (const match of line.matchAll(/['\\\"]([a-z][a-z0-9_]*)['\\\"]\\s*:/g)) add(match[1], true);\n  for (const match of line.matchAll(/\\[['\\\"]([a-z][a-z0-9_]*)['\\\"]\\]/g)) add(match[1], true);\n  for (const match of line.matchAll(/(?:^|[,{}]\\s*)([a-z][A-Za-z0-9_]*)\\??\\s*:/g)) add(match[1]);\n  const declaration = line.match(/\\b(?:final|late\\s+final|pub(?:\\([^)]*\\))?)\\s+(?:[A-Za-z0-9_<>,?. ()]+\\s+)?([a-z][A-Za-z0-9_]*)\\s*[;:]/);\n  if (declaration) add(declaration[1]);\n  if (extension === '.proto') {\n    const proto = line.match(/^\\s*(?:repeated\\s+)?[A-Za-z][A-Za-z0-9_.<>]*\\s+([a-z][a-z0-9_]*)\\s*=\\s*\\d+/);\n    if (proto) add(proto[1], true);\n  }\n  if (extension === '.sql') {\n    const sql = line.match(/^\\s*([a-z][a-z0-9_]*)\\s+(?:BIGINT|BLOB|BOOLEAN|INTEGER|REAL|TEXT)\\b/i);\n    if (sql) add(sql[1], true);\n  }\n  return [...fields.values()];\n}\n\nexport function addedClosedValues(line, concepts, valueSets) {\n  const violations = [];\n  for (const concept of concepts.values()) {\n    if (!concept.value_set_id) continue;\n    const snake = concept.field_name;\n    const camel = toCamelCase(snake);\n    const field = `(?:['\\\"])?(?:${escapeRegex(snake)}|${escapeRegex(camel)})(?:['\\\"])?`;\n    const assignment = new RegExp(`${field}\\\\s*(?::|={1,3}|!={1,2})\\\\s*['\\\"]([A-Za-z][A-Za-z0-9_-]*)['\\\"]`, 'g');\n    const allowed = new Set(valueSets.get(concept.value_set_id).values.map((entry) => String(entry.value)));\n    for (const match of line.matchAll(assignment)) {\n      const candidate = match[1];\n      if (allowed.has(candidate)) continue;\n      violations.push({ conceptId: concept.concept_id, value: candidate });\n    }\n  }\n  return violations;\n}\n\nfunction repositoryFiles() {\n  const output = execFileSync('git', ['ls-files', '-co', '--exclude-standard', '-z'], {\n    cwd: repositoryRoot,\n    encoding: 'utf8',\n    maxBuffer: 64 * 1024 * 1024,\n  });\n  return [...new Set(output.split('\\0').filter(Boolean))].sort((a, b) => a.localeCompare(b));\n}\n\nfunction baseFieldNames(baseRef) {\n  const output = execFileSync('git', ['grep', '-h', '-o', '-I', '-E', '[A-Za-z][A-Za-z0-9_]{2,}', baseRef, '--'], {\n    cwd: repositoryRoot,\n    encoding: 'utf8',\n    maxBuffer: 128 * 1024 * 1024,\n  });\n  return new Set(output.split('\\n').filter(Boolean).map(toSnakeCase));\n}\n\nexport function changedDictionaryViolations(baseRef, dictionary) {\n  execFileSync('git', ['rev-parse', '--verify', baseRef], { cwd: repositoryRoot, stdio: 'ignore' });\n  const diff = execFileSync('git', ['diff', '--unified=0', '--no-color', baseRef, '--'], {\n    cwd: repositoryRoot,\n    encoding: 'utf8',\n    maxBuffer: 64 * 1024 * 1024,\n  });\n  const additions = new Map();\n  const valueViolations = [];\n  let currentPath = '';\n  for (const line of diff.split('\\n')) {\n    if (line.startsWith('+++ b/')) {\n      currentPath = line.slice(6);\n      continue;\n    }\n    if (!currentPath || !line.startsWith('+') || line.startsWith('+++')) continue;\n    if (!sourceExtensions.test(currentPath) || matchesAny(currentPath, dictionary.ignoredPaths)) continue;\n    const added = line.slice(1);\n    for (const field of addedFieldNames(added, extname(currentPath))) {\n      const value = additions.get(field.fieldName) ?? { files: new Set(), strong: false };\n      value.files.add(currentPath);\n      value.strong ||= field.strong;\n      additions.set(field.fieldName, value);\n    }\n    if (!/(?:^|\\/)(?:test|tests)(?:\\/|$)/.test(currentPath)) {\n      for (const violation of addedClosedValues(added, dictionary.concepts, dictionary.valueSets)) {\n        valueViolations.push(`${currentPath}: ${violation.conceptId} 新增未登记闭集值 ${violation.value}`);\n      }\n    }\n  }\n  const registered = new Set([...dictionary.concepts.values()].map((concept) => concept.field_name));\n  const existing = baseFieldNames(baseRef);\n  const violations = [];\n  for (const [fieldName, value] of [...additions].sort(([left], [right]) => left.localeCompare(right))) {\n    if (registered.has(fieldName) || (!value.strong && value.files.size < 2) || existing.has(fieldName)) continue;\n    violations.push(`新增契约字段 ${fieldName} 尚未登记：${[...value.files].sort().join(', ')}`);\n  }\n  return [...violations, ...valueViolations];\n}\n\nexport function checkRepository(baseRef = '') {\n  const dictionary = loadDictionary();\n  const files = repositoryFiles().filter((path) => (\n    sourceExtensions.test(path)\n    && existsSync(join(repositoryRoot, path))\n    && !matchesAny(path, dictionary.ignoredPaths)\n  ));\n  const violations = [];\n  if (baseRef) violations.push(...changedDictionaryViolations(baseRef, dictionary));\n\n  const forbiddenFields = [...dictionary.concepts.values()].flatMap((concept) => concept.forbidden_names.map((forbiddenName) => ({\n    canonicalName: concept.field_name,\n    forbiddenName,\n    legacyReads: concept.legacy_reads ?? [],\n    paths: concept.paths,\n    patterns: fieldPatterns(forbiddenName),\n  })));\n  for (const path of files) {\n    const candidates = forbiddenFields.filter((field) => !field.paths || matchesAny(path, field.paths));\n    if (candidates.length === 0) continue;\n    const text = readFileSync(join(repositoryRoot, path), 'utf8');\n    const present = candidates.filter((field) => text.includes(field.forbiddenName));\n    if (present.length === 0) continue;\n    const lines = text.split('\\n');\n    for (let index = 0; index < lines.length; index += 1) {\n      for (const field of present) {\n        const used = path.endsWith('.md')\n          ? markdownUsesFieldName(lines[index], field.forbiddenName)\n          : field.patterns.some((pattern) => pattern.test(lines[index]));\n        if (used && isDeclaredLegacyRead(lines[index], path, field.forbiddenName, field.legacyReads)) continue;\n        if (used) violations.push(`${path}:${index + 1}: 字段 ${field.forbiddenName} 已废弃，应使用 ${field.canonicalName} / ${toCamelCase(field.canonicalName)}`);\n      }\n    }\n  }\n  if (violations.length > 0) fail(`统一数据字典检查失败：\\n  - ${violations.join('\\n  - ')}`);\n  const values = [...dictionary.valueSets.values()].reduce((sum, valueSet) => sum + valueSet.values.length, 0);\n  return { files: files.length, fields: dictionary.concepts.size, valueSets: dictionary.valueSets.size, values };\n}\n\nconst invokedPath = process.argv[1] ? pathToFileURL(resolve(process.argv[1])).href : '';\nif (import.meta.url === invokedPath) {\n  try {\n    const baseIndex = process.argv.indexOf('--base-ref');\n    if (baseIndex >= 0 && !process.argv[baseIndex + 1]) fail('--base-ref 缺少 Git ref');\n    const result = checkRepository(baseIndex >= 0 ? process.argv[baseIndex + 1] : '');\n    console.log(`统一数据字典检查通过：${result.fields} 个字段，${result.valueSets} 个值集，${result.values} 个闭集值，${result.files} 个第一方文件。`);\n  } catch (error) {\n    console.error(error instanceof Error ? error.message : String(error));\n    process.exitCode = 1;\n  }\n}\n","guardrails":"#!/usr/bin/env bash\nset -euo pipefail\n\nbase_ref=\"${BASE_REF:-origin/main}\"\n\n# 中文注释：GMB 是独立公开仓库，门禁不得依赖 CitizenConsole 私仓或 AI memory。\n[[ -f shared/data-dictionary.json ]] || { echo \"缺少公开数据字典。\" >&2; exit 1; }\nif [[ -e memory || -e citizenconsole || -e AGENTS.md || -e CODEX.md || -e CLAUDE.md ]]; then\n  echo \"GMB 根目录检测到私人 AI 或 CitizenConsole 残留。\" >&2\n  exit 1\nfi\n\n# 中文注释：全仓禁止中国国旗字符；用 UTF-8 八进制构造，避免规则本身成为命中项。\nforbidden_cn_flag=\"$(printf '\\360\\237\\207\\250\\360\\237\\207\\263')\"\nflag_files=\"$(git grep --untracked -l -I -F \"$forbidden_cn_flag\" -- . || true)\"\nif [[ -n \"$flag_files\" ]]; then\n  echo \"检测到禁止使用的中国国旗字符（仅报告文件）：\" >&2\n  printf '  - %s\\n' \"$flag_files\" >&2\n  exit 1\nfi\n\nif ! git rev-parse --verify \"$base_ref\" >/dev/null 2>&1; then\n  branch=\"${base_ref#origin/}\"\n  git fetch origin \"$branch\" --depth=1\nfi\n\nmerge_base=\"$(git merge-base HEAD \"$base_ref\")\"\ndeclare -a changed_files=()\nwhile IFS= read -r file; do\n  [[ -n \"$file\" ]] && changed_files+=(\"$file\")\ndone < <(git diff --name-only \"$merge_base\")\nwhile IFS= read -r file; do\n  [[ -n \"$file\" ]] && changed_files+=(\"$file\")\ndone < <(git ls-files --others --exclude-standard)\n\nif [[ \"${#changed_files[@]}\" -eq 0 ]]; then\n  echo \"未检测到变更文件，跳过公开仓库增量门禁。\"\n  exit 0\nfi\n\n# 中文注释：强特征机密扫描只报告路径，禁止把命中值写入 Actions 日志。\nsecret_files=\"$(git grep --untracked -l -I -E 'BEGIN (RSA |EC |OPENSSH )?PRIVATE KEY|AKIA[0-9A-Z]{16}|github_pat_[A-Za-z0-9_]{20,}|gh[pousr]_[A-Za-z0-9]{30,}|sk_live_[A-Za-z0-9]{16,}' -- . ':!citizenserve/test/release_manifest.test.ts' ':!citizenweb/test/release_manifest.test.mjs' || true)\"\nif [[ -n \"$secret_files\" ]]; then\n  echo \"公开仓库检测到疑似真实机密（仅报告文件）：\" >&2\n  printf '  - %s\\n' \"$secret_files\" >&2\n  exit 1\nfi\n\ntodo_word=\"TO\"\"DO\"\nfixme_word=\"FIX\"\"ME\"\nresidual_regex=\"(console\\\\.log\\\\(|debugger;|dbg!\\\\(|todo!\\\\(|unimplemented!\\\\(|\\\\b${todo_word}\\\\b|\\\\b${fixme_word}\\\\b)\"\nversion_regex='([A-Za-z0-9][._:-]v[0-9]+|/(api/)?v[0-9]+|[A-Za-z0-9]_V[0-9]+|schema_version|cache_version|protocol_version|tag[[:space:]]*=[[:space:]]*[\\\"]v[0-9]+)'\ndeclare -a residual_hits=()\ndeclare -a comment_hits=()\ndeclare -a version_hits=()\ndeclare -a lint_hits=()\ndeclare -a insecure_transport_hits=()\n\nis_code_file() {\n  case \"$1\" in\n    *.rs|*.dart|*.ts|*.tsx|*.js|*.jsx|*.mjs|*.sh|*.py|*.sql|*.swift|*.kt|*.kts) return 0 ;;\n    *) return 1 ;;\n  esac\n}\n\nskip_generated_or_vendor() {\n  case \"$1\" in\n    citizenapp/smoldot/pow/*|citizenapp/assets/topup/walletconnect.bundle.js|citizenserve/worker-configuration.d.ts|*/dist/*|*/build/*|*/target/*|*/node_modules/*|*/GeneratedPluginRegistrant.*|*.g.dart|*.pb.dart|*.pbjson.dart|*.pbenum.dart|.github/scripts/gmb-repository/ci-repository.mjs) return 0 ;;\n    *) return 1 ;;\n  esac\n}\n\nhas_chinese_comment() {\n  # 中文注释：Unicode Script=Han 不依赖 runner 的本地排序规则，避免 grep 把汉字端点判为非法范围。\n  node -e 'const fs = require(\"node:fs\"); process.exit(/(?:\\/\\/|\\/\\*|\\*|#).*\\p{Script=Han}/u.test(fs.readFileSync(0, \"utf8\")) ? 0 : 1)'\n}\n\nsanitize_version_line() {\n  local line=\"$1\"\n  # 中文注释：Apple 官方 API/audience 与四条产品正式 Release Tag 是外部接口或软件版本身份，\n  # 不属于一方自定义协议标识；只精确移除这些已登记形态，继续阻断其它版本化协议。\n  line=\"${line//QR_V1/}\"\n  line=\"${line//QrProtocol.qrV1/}\"\n  line=\"${line//QrProtocols.qrV1/}\"\n  line=\"${line//APK v2\\/v3/}\"\n  line=\"${line//APK Signature Scheme v2\\/v3/}\"\n  line=\"$(printf '%s\\n' \"$line\" | sed -E \\\n    -e 's/Uuid::new_v[45]//g' \\\n    -e 's/arm64-v8a//g' \\\n    -e 's/armeabi-v7a//g' \\\n    -e 's/libbarhopper_v[0-9]+//g' \\\n    -e 's/RSASSA-PKCS1-v1_5//g' \\\n    -e 's/sc-rpc-spec-v2//g' \\\n    -e 's#https://api\\.appstoreconnect\\.apple\\.com/v1##g' \\\n    -e 's/appstoreconnect-v1//g' \\\n    -e 's#/(upload/)?androidpublisher/v[0-9]+##g' \\\n    -e 's/citizen(app|wallet)-(ios|android)-v[0-9]+\\.[0-9]+\\.[0-9]+//g' \\\n    -e 's/citizen(serve-cloudflare|web)-v[0-9]+\\.[0-9]+\\.[0-9]+//g')\"\n  printf '%s\\n' \"$line\"\n}\n\nfor file in \"${changed_files[@]}\"; do\n  [[ -f \"$file\" ]] || continue\n  is_code_file \"$file\" || continue\n  skip_generated_or_vendor \"$file\" && continue\n\n  added_lines=\"$(git diff --unified=0 \"$merge_base\" -- \"$file\" | grep -E '^\\+' | grep -vE '^\\+\\+\\+' || true)\"\n  [[ -n \"$added_lines\" ]] || continue\n\n  # 中文注释：第一方新增网络地址只允许 HTTPS/WSS，禁止明文协议及任何降级入口。\n  if printf '%s\\n' \"$added_lines\" | grep -Eq '(http|ws)://'; then\n    insecure_transport_hits+=(\"${file}: 本次新增内容使用明文网络协议\")\n  fi\n\n  # 中文注释：只拦本次新增残留；命令行工具的结果输出不是浏览器调试日志。\n  if [[ \"$file\" != .github/scripts/*/*.mjs ]] && printf '%s\\n' \"$added_lines\" | grep -Eq \"$residual_regex\"; then\n    residual_hits+=(\"${file}: 本次新增内容含开发残留\")\n  fi\n\n  added_count=\"$(printf '%s\\n' \"$added_lines\" | sed '/^[[:space:]]*+?[[:space:]]*$/d' | wc -l | tr -d ' ')\"\n  if [[ \"$added_count\" -ge 12 ]] && ! printf '%s\\n' \"$added_lines\" | has_chinese_comment; then\n    comment_hits+=(\"${file}: 新增 ${added_count} 行实现但没有中文注释\")\n  fi\n\n  while IFS= read -r line; do\n    sanitized=\"$(sanitize_version_line \"$line\")\"\n    if printf '%s\\n' \"$sanitized\" | grep -Eq \"$version_regex\"; then\n      version_hits+=(\"${file}: 新增非 QR_V1 的一方版本化标识\")\n      break\n    fi\n  done <<< \"$added_lines\"\n\n  if [[ \"$file\" == *.rs ]] && printf '%s\\n' \"$added_lines\" | grep -Eq '#!?\\[allow\\((dead_code|unused)'; then\n    if ! printf '%s\\n' \"$added_lines\" | has_chinese_comment; then\n      lint_hits+=(\"${file}: 新增编译器抑制但没有中文理由\")\n    fi\n  fi\ndone\n\nif [[ \"${#insecure_transport_hits[@]}\" -gt 0 ]]; then\n  echo \"检测到禁止的明文网络协议：\" >&2\n  printf '  - %s\\n' \"${insecure_transport_hits[@]}\" >&2\n  exit 1\nfi\nif [[ \"${#residual_hits[@]}\" -gt 0 ]]; then\n  echo \"检测到开发残留：\" >&2\n  printf '  - %s\\n' \"${residual_hits[@]}\" >&2\n  exit 1\nfi\nif [[ \"${#comment_hits[@]}\" -gt 0 ]]; then\n  echo \"检测到较大代码改动缺少中文注释：\" >&2\n  printf '  - %s\\n' \"${comment_hits[@]}\" >&2\n  exit 1\nfi\nif [[ \"${#version_hits[@]}\" -gt 0 ]]; then\n  echo \"检测到非 QR_V1 的一方版本化标识：\" >&2\n  printf '  - %s\\n' \"${version_hits[@]}\" >&2\n  exit 1\nfi\nif [[ \"${#lint_hits[@]}\" -gt 0 ]]; then\n  echo \"检测到缺少中文理由的编译器抑制：\" >&2\n  printf '  - %s\\n' \"${lint_hits[@]}\" >&2\n  exit 1\nfi\n\necho \"GMB 公开仓库门禁通过。\"\n","golden-vectors":"#!/usr/bin/env node\n// 校验密码学金标向量在各端镜像之间保持一致。\n//\n// 契约:citizenchain/runtime/primitives 是签名域与账户派生的规范实现,其 tests/fixtures/\n// 下的向量文件是唯一真源(文件 `_comment` 已自述 \"canonical, Rust 权威源\")。\n// citizenapp / citizenwallet / Worker 各自持有镜像副本,供本端金标测试独立回归。\n//\n// 为什么需要本脚本:各端金标测试只验证「本端实现算出的值 == 本端向量文件」。同时改动\n// 本端实现与本端向量,该端 CI 依旧全绿,两端就此静默分叉。只有跨端比对能拦住这种漂移。\n//\n// 比对规则:\n//   1. 按语义键对齐,**禁止按数组下标对齐**——各端向量顺序与条数本就不同,\n//      按下标比会产生大量假阳性(2026-08-01 审计曾因此误报 45 处冲突)。\n//   2. 只比密码学值。`layout` / `_comment` / `source` 等人类可读描述各端措辞不同\n//      (如 `pubkey(32)` 与 `signer_public_key(32)`),属噪音,强制统一只会逼人改文案凑 CI。\n//   3. 镜像必须是真源的子集:镜像出现真源没有的向量即失败(说明该端自造了向量)。\n//   4. 镜像未覆盖到的真源向量只报告、不失败——各端职责不同,覆盖子集是正常设计。\n//      签名域是安全关键例外:CitizenApp 镜像必须完整覆盖真源,缺一条直接失败。\n//\n// 用法:node .github/scripts/gmb-repository/ci-repository.mjs golden-vectors\n// 退出码:0=一致;1=发现漂移或读文件失败。\n\nimport { readFileSync } from 'node:fs';\nimport { fileURLToPath } from 'node:url';\nimport { dirname, join, relative } from 'node:path';\n\nconst repoRoot = process.env.GMB_REPOSITORY_ROOT || process.cwd();\n\nconst CANONICAL_DIR = join(\n  repoRoot, 'citizenchain', 'runtime', 'primitives', 'tests', 'fixtures',\n);\n\n/**\n * 各金标组的比对定义。\n *\n * keyFields   决定「同一条向量」的语义键,必须唯一确定该向量的密码学输出。\n * valueFields 参与比对的密码学值;缺字段即视为不一致(挡住镜像悄悄删字段)。\n * topFields   顶层标量参数,四端必须全等。\n */\nconst GROUPS = [\n  {\n    name: 'signing_domain_vectors',\n    file: 'signing_domain_vectors.json',\n    // op_tag + payload 唯一决定 blake2_256(GMB || op_tag || payload)\n    keyFields: ['op_tag', 'scale_payload_hex'],\n    valueFields: ['message_hex'],\n    topFields: ['domain'],\n    requireAll: true,\n    mirrors: [\n      'citizenapp/test/signer/fixtures/signing_domain_vectors.json',\n      // Worker(TS) 与 citizenwallet 不在此登记:两端都没有镜像文件,分别由\n      // citizenserve/test/signing_message.test.ts 和\n      // citizenwallet/test/signer/signing_domain_golden_test.dart 直读上面这份真源。\n      // 零副本比\"副本 + 比对\"更强——漂移在物理上不可能发生。\n    ],\n  },\n  {\n    name: 'binary_prefix_domain_vectors',\n    file: 'binary_prefix_domain_vectors.json',\n    keyFields: ['name'],\n    valueFields: ['op_tag', 'prefix_hex', 'payload_hex', 'total_len'],\n    topFields: ['domain'],\n    mirrors: [\n      'citizenapp/test/signer/fixtures/binary_prefix_domain_vectors.json',\n      'citizenwallet/test/signer/fixtures/binary_prefix_domain_vectors.json',\n    ],\n  },\n  {\n    name: 'account_derive_vectors',\n    file: 'account_derive_vectors.json',\n    keyFields: ['cid_number', 'kind'],\n    valueFields: ['account_id'],\n    topFields: ['domain', 'ss58_format'],\n    mirrors: [\n      'citizenapp/test/governance/shared/fixtures/account_derive_vectors.json',\n    ],\n  },\n];\n\nlet failed = false;\n\nfunction fail(message) {\n  console.error(`[golden-vectors] ${message}`);\n  failed = true;\n}\n\nfunction readJson(path) {\n  try {\n    return JSON.parse(readFileSync(path, 'utf8'));\n  } catch (error) {\n    fail(`无法读取或解析 ${relative(repoRoot, path)}: ${error.message}`);\n    return null;\n  }\n}\n\n/** hex 与标识符大小写在各端书写习惯不同,比对前统一归一;数字保持原值。 */\nfunction normalize(value) {\n  return typeof value === 'string' ? value.toLowerCase() : value;\n}\n\nfunction vectorKey(vector, keyFields) {\n  return keyFields.map((field) => normalize(vector[field])).join('|');\n}\n\n/** 建索引,顺带挡住同一文件内语义键重复(会让比对静默漏掉后一条)。 */\nfunction indexVectors(vectors, keyFields, label) {\n  const map = new Map();\n  for (const vector of vectors) {\n    const key = vectorKey(vector, keyFields);\n    if (map.has(key)) {\n      fail(`${label} 存在重复向量键 ${key}`);\n    }\n    map.set(key, vector);\n  }\n  return map;\n}\n\nfunction checkGroup(group) {\n  const canonicalPath = join(CANONICAL_DIR, group.file);\n  const canonical = readJson(canonicalPath);\n  if (canonical === null) return;\n  if (!Array.isArray(canonical.vectors) || canonical.vectors.length === 0) {\n    fail(`${group.name} 真源没有向量`);\n    return;\n  }\n\n  const canonicalMap = indexVectors(\n    canonical.vectors, group.keyFields, `${group.name} 真源`,\n  );\n\n  for (const mirrorRelative of group.mirrors) {\n    const mirror = readJson(join(repoRoot, mirrorRelative));\n    if (mirror === null) continue;\n\n    for (const field of group.topFields) {\n      if (normalize(mirror[field]) !== normalize(canonical[field])) {\n        fail(\n          `${mirrorRelative} 顶层 ${field} 与真源不一致:` +\n          `真源=${canonical[field]} 镜像=${mirror[field]}`,\n        );\n      }\n    }\n\n    if (!Array.isArray(mirror.vectors)) {\n      fail(`${mirrorRelative} 缺少 vectors 数组`);\n      continue;\n    }\n    const mirrorMap = indexVectors(\n      mirror.vectors, group.keyFields, mirrorRelative,\n    );\n\n    for (const [key, mirrorVector] of mirrorMap) {\n      const canonicalVector = canonicalMap.get(key);\n      if (canonicalVector === undefined) {\n        fail(\n          `${mirrorRelative} 存在真源没有的向量 ${key};` +\n          `镜像不得自造向量,请先在 ${relative(repoRoot, canonicalPath)} 登记`,\n        );\n        continue;\n      }\n      for (const field of group.valueFields) {\n        const expected = normalize(canonicalVector[field]);\n        const actual = normalize(mirrorVector[field]);\n        if (expected === undefined) {\n          fail(`${group.name} 真源向量 ${key} 缺少字段 ${field}`);\n          continue;\n        }\n        if (actual !== expected) {\n          fail(\n            `${mirrorRelative} 向量 ${key} 的 ${field} 与真源不一致\\n` +\n            `    真源 = ${canonicalVector[field]}\\n` +\n            `    镜像 = ${mirrorVector[field]}`,\n          );\n        }\n      }\n    }\n\n    const uncovered = [...canonicalMap.keys()].filter((k) => !mirrorMap.has(k));\n    if (uncovered.length > 0) {\n      const message = `${mirrorRelative} 未覆盖 ${uncovered.length} 条真源向量: ${uncovered.join(', ')}`;\n      if (group.requireAll) {\n        fail(message);\n      } else {\n        // 非签名域允许按端职责覆盖子集，但继续输出便于人工复核。\n        console.log(`[golden-vectors] 提示:${message}`);\n      }\n    }\n    console.log(\n      `[golden-vectors] ${group.name}: ${mirrorRelative} 已比对 ${mirrorMap.size} 条`,\n    );\n  }\n}\n\nfor (const group of GROUPS) {\n  checkGroup(group);\n}\n\nif (failed) {\n  console.error(\n    '[golden-vectors] 金标向量跨端不一致。' +\n    '真源在 citizenchain/runtime/primitives/tests/fixtures/,改动真源后必须同步全部镜像。',\n  );\n  process.exit(1);\n}\n\nconsole.log('[golden-vectors] 全部金标向量跨端一致');\n","pallet-registry":"#!/usr/bin/env node\n// 校验前端 pallet 注册表(Dart)与链上 construct_runtime 的 pallet 索引一致。\n//\n// 契约:citizenchain runtime 是 pallet 索引唯一真源;citizenwallet 与 citizenapp 各有一份\n// pallet_registry.dart 镜像。链上 pallet 重排后若 Dart 注册表未同步,会往错误 pallet 发交易。\n// 本脚本在 CI 静态比对:每个 Dart `xxxPallet = N` 常量,其 N 必须等于链上同名 pallet 的索引。\n//\n// 用法:node .github/scripts/gmb-repository/ci-repository.mjs pallet-registry\n// 退出码:0=一致;1=发现漂移或读文件失败。\n\nimport { readFileSync } from 'node:fs';\nimport { fileURLToPath } from 'node:url';\nimport { dirname, join } from 'node:path';\n\nconst repoRoot = process.env.GMB_REPOSITORY_ROOT || process.cwd();\n\nconst RUNTIME_LIB = join(repoRoot, 'citizenchain', 'runtime', 'src', 'lib.rs');\nconst DART_REGISTRIES = [\n  join(repoRoot, 'citizenwallet', 'lib', 'signer', 'pallet_registry.dart'),\n  join(repoRoot, 'citizenapp', 'lib', 'rpc', 'pallet_registry.dart'),\n];\n\nfunction read(path) {\n  try {\n    return readFileSync(path, 'utf8');\n  } catch (error) {\n    console.error(`[pallet-registry-sync] 无法读取 ${path}: ${error.message}`);\n    process.exit(1);\n  }\n}\n\n// 链上真源:construct_runtime 的 `#[runtime::pallet_index(N)] pub type Name = ...;`\nfunction parseChainIndexToName(source) {\n  const map = new Map();\n  const re = /#\\[runtime::pallet_index\\((\\d+)\\)\\]\\s*\\n\\s*pub type (\\w+)\\s*=/g;\n  let match;\n  while ((match = re.exec(source)) !== null) {\n    map.set(Number(match[1]), match[2]);\n  }\n  return map;\n}\n\n// Dart 端 pallet 常量:`static const int? xxxPallet = N;`(排除引用 PalletRegistry 的间接赋值)\nfunction parseDartPalletConsts(source) {\n  const consts = [];\n  const re = /static const (?:int\\s+)?(\\w+Pallet)\\s*=\\s*(\\d+);/g;\n  let match;\n  while ((match = re.exec(source)) !== null) {\n    consts.push({ constName: match[1], index: Number(match[2]) });\n  }\n  return consts;\n}\n\n// Dart camelCase 常量名 → 链上 PascalCase pallet 名:去 `Pallet` 后缀,首字母大写。\n// 约定:citizenwallet/citizenapp 的 pallet 常量按链上 pallet 类型名的 camelCase 命名。\nfunction dartConstToPascal(constName) {\n  const base = constName.replace(/Pallet$/, '');\n  return base.charAt(0).toUpperCase() + base.slice(1);\n}\n\nconst chainIndexToName = parseChainIndexToName(read(RUNTIME_LIB));\nif (chainIndexToName.size === 0) {\n  console.error('[pallet-registry-sync] 未能从 construct_runtime 解析到任何 pallet 索引,检查 runtime/src/lib.rs 格式');\n  process.exit(1);\n}\n\nconst problems = [];\nlet checked = 0;\n\nfor (const registryPath of DART_REGISTRIES) {\n  const consts = parseDartPalletConsts(read(registryPath));\n  const rel = registryPath.slice(repoRoot.length + 1);\n  if (consts.length === 0) {\n    problems.push(`${rel}: 未解析到任何 pallet 常量(格式变了?)`);\n    continue;\n  }\n  for (const { constName, index } of consts) {\n    checked += 1;\n    const expectedName = dartConstToPascal(constName);\n    const chainName = chainIndexToName.get(index);\n    if (chainName === undefined) {\n      problems.push(`${rel}: ${constName}=${index} 指向的索引在链上不存在`);\n    } else if (chainName !== expectedName) {\n      problems.push(\n        `${rel}: ${constName}=${index} 期望链上 pallet「${expectedName}」,但索引 ${index} 实为「${chainName}」(pallet 重排未同步)`,\n      );\n    }\n  }\n}\n\nif (problems.length > 0) {\n  console.error('[pallet-registry-sync] 前端 pallet 注册表与链上 construct_runtime 不一致:');\n  for (const problem of problems) console.error(`  ✗ ${problem}`);\n  console.error('修复:更新对应 pallet_registry.dart 使索引与 citizenchain/runtime/src/lib.rs 一致。');\n  process.exit(1);\n}\n\nconsole.log(`[pallet-registry-sync] OK:${checked} 个前端 pallet 常量与链上 construct_runtime 全部一致。`);\n"});
const [command, ...argumentsList] = process.argv.slice(2);
if (!command || !Object.hasOwn(implementations, command)) {
  console.error(`未登记动作子命令：${command || '(empty)'}；允许值：${Object.keys(implementations).join(', ')}`);
  process.exit(2);
}
const temporaryDirectory = mkdtempSync(join(tmpdir(), 'gmb-action-'));
const shellCommand = command === 'linux-deps' || command === 'guardrails';
const implementationPath = join(temporaryDirectory, shellCommand ? 'implementation.sh' : 'implementation.mjs');
try {
  writeFileSync(implementationPath, implementations[command], { mode: 0o700 });
  const result = spawnSync(shellCommand ? '/bin/bash' : process.execPath, [realpathSync(implementationPath), ...argumentsList], {
    cwd: repositoryRoot,
    env: { ...process.env, GMB_REPOSITORY_ROOT: repositoryRoot },
    stdio: 'inherit',
  });
  if (result.error) throw result.error;
  process.exitCode = result.status ?? 1;
} finally {
  rmSync(temporaryDirectory, { recursive: true, force: true });
}
